-- Hero Architect builds for the 21 CoA classes (70 specializations).
--
-- Source: the wowstar.online community specialization guide, cross-checked against
-- the Zygor Talent Advisor CoA talent data. Specialization names and the one-line
-- summary in `subtext` are taken from the client `ChrSpecs.dbc` / `ChrClasses.dbc`
-- of the Chinese patch, so an entry reads exactly like the specialization screen.
--
-- `class` is the `ChrClasses` ClassID; 12-32 are the CoA hero classes. Entries
-- 1001-1070 are reserved for this set, while the catalog seeded by
-- `rev_20261011_01_coa_build_creator.sql` uses 1-357. `owner_account` stays 0:
-- these are server-owned builds without a publishing account, and `author` carries
-- the credit instead.
--
-- Weapon and armor restrictions are per-class defaults; a build that needs a
-- different set is edited in game (收藏 -> 原型). The catalog is loaded once by
-- `AscensionBuildCreator::LoadCatalog()`, so apply this file and restart
-- worldserver, or drop it into data/sql/updates/pending_db_characters/.

START TRANSACTION;

DELETE FROM `coa_build_creator` WHERE `entry` BETWEEN 1001 AND 1070;

INSERT INTO `coa_build_creator` (`entry`, `id`, `leveling_id`, `pve_id`, `pvp_id`, `class`, `author`, `name`, `subtext`, `description`, `icon`, `upvotes`, `created`, `updated`, `category`, `roles`, `primary_stat`, `flags`, `difficulty`) VALUES
(1001, '718e3e05-14fd-50e4-910c-dd470ebf680d', '', '', '', 12, 'Sidekick', '野蛮人 · 先祖', '借助先祖之力与战斗豪饮，强化盟友。', '### 概述\n先祖（Ancestry）· 野蛮人 专精\n\n### 定位\n辅助\n\n官方简介：借助先祖之力与战斗豪饮，强化盟友。\n\n### 核心\n先祖召唤（Ancestor''s Call，r1,c4）：召唤永久存在的「尊崇先祖」宠物；整棵天赋树（Ale of The God-King、Drunken Frenzy、The Spins、Might of Utgarde）几乎都是为强化它而点。\n\n### 来源\nwowstar.online社区推荐专精。', 'ability_warrior_bloodbath', 0, 1795651200, 1795651200, 1, 15, 1, 0, 0),
(1002, 'c52155b8-6434-51ba-894c-8c99862f011e', '', '', '', 12, 'Sidekick', '野蛮人 · 残暴', '挥舞双手武器，以强力打击撕碎敌人。', '### 概述\n残暴（Brutality）· 野蛮人 专精\n\n### 定位\n近战 DPS\n\n官方简介：挥舞双手武器，以强力打击撕碎敌人。\n\n### 核心\n斩首（Decapitate，r0,c4）：把怒气全部倾倒的斩杀终结技；其余节点（Beheader、Overkill、Headlopper、Spiked Weapons）都在为它供能与放大。\n\n### 来源\nwowstar.online社区推荐专精。', 'ability_warrior_bloodbath', 0, 1795651200, 1795651200, 1, 15, 1, 0, 0),
(1003, 'fb341f4f-5142-5387-8747-608b68578b12', '', '', '', 12, 'Sidekick', '野蛮人 · 猎首', '投掷长矛与飞斧，远程压制猎物。', '### 概述\n猎首（Headhunting）· 野蛮人 专精\n\n### 定位\n近战 DPS\n\n官方简介：投掷长矛与飞斧，远程压制猎物。\n\n### 核心\n开膛投掷（Gutspiller，r2,c6）：流血＋爆发的掷斧核心；整棵树（Guts Splatter、Entrails、To The Bone、Payback）都为放大它而设计。\n\n### 来源\nwowstar.online社区推荐专精。', 'ability_warrior_bloodbath', 0, 1795651200, 1795651200, 1, 15, 1, 0, 0),
(1004, 'dad1f111-9e17-5d10-a79d-3cd5a50c8870', '', '', '', 22, 'Sidekick', '时光术士 · 工艺师', '以法杖攻击积聚时光回响，释放集中爆发。', '### 概述\n工艺师（Artificer）· 时光术士 专精\n\n### 定位\n远程 DPS（魔杖／资源型）\n\n官方简介：以法杖攻击积聚时光回响，释放集中爆发。\n\n### 核心\n回声碎片（Echo Fragments，r0,c10）：10 级被动，魔杖攻击产出「回声碎片」；这是 Distortion 与 Continuum 系技能共用的资源。\n\n### 来源\nwowstar.online社区推荐专精。', 'spell_arcane_temporal', 0, 1795651200, 1795651200, 1, 15, 3, 0, 0),
(1005, 'ef6a2be9-79a6-556c-aa12-c9483b567bbd', '', '', '', 22, 'Sidekick', '时光术士 · 永恒', '驾驭永恒龙军团的混乱力量摧毁敌人。', '### 概述\n永恒（Infinite）· 时光术士 专精\n\n### 定位\n远程 DPS（周期与爆发施法）\n\n官方简介：驾驭永恒龙军团的混乱力量摧毁敌人。\n\n### 核心\n混沌化身（Incarnation of Chaos，r5,c1）：标志性爆发窗口，重置 Chromatic Shard 并消除其下一冷却，同时提供 15% 全伤害增益。\n\n### 来源\nwowstar.online社区推荐专精。', 'spell_arcane_temporal', 0, 1795651200, 1795651200, 1, 15, 3, 0, 0),
(1006, '024e83d6-6aed-54fb-ad85-6a52449f4be3', '', '', '', 22, 'Sidekick', '时光术士 · 时光', '操纵时间治愈盟友，并延缓伤害。', '### 概述\n时光（Time）· 时光术士 专精\n\n### 定位\n辅助（治疗）\n\n官方简介：操纵时间治愈盟友，并延缓伤害。\n\n### 核心\n史诗复原（Epic Recovery，r8,c6）：施放 Epoch 时，对最多 5 名带有你「加速复原」HoT 的队友再各触发一次 1 阶 Epoch，把单体治疗变成群体治疗。\n\n### 来源\nwowstar.online社区推荐专精。', 'spell_arcane_temporal', 0, 1795651200, 1795651200, 1, 15, 3, 0, 0),
(1007, '9258b409-02c6-5c48-8160-e20ef0a789e3', '', '', '', 25, 'Sidekick', '邪教徒 · 腐蚀', '引导克苏恩之力，释放触须与虚空魔法。', '### 概述\n腐蚀（Corruption）· 邪教徒 专精\n\n### 定位\n远程 DPS\n\n官方简介：引导克苏恩之力，释放触须与虚空魔法。\n\n### 核心\n恐惧箭齐射（Horrorbolt Volley，r9,c2）：每第三次施法把核心填充技变成 5 目标范围爆发核弹。\n\n### 来源\nwowstar.online社区推荐专精。', 'spell_shadow_unholystrength', 0, 1795651200, 1795651200, 1, 15, 3, 0, 0),
(1008, '5e19a014-029c-5346-91a9-9ed6a039ad91', '', '', '', 25, 'Sidekick', '邪教徒 · 无畏', '以亚煞极的力量强化防御，承受攻击。', '### 概述\n无畏（Dreadnought）· 邪教徒 专精\n\n### 定位\n坦克\n\n官方简介：以亚煞极的力量强化防御，承受攻击。\n\n### 核心\n伊煞极化身（Embodiment of Y''shaarj，r9,c7）：虚空护盾吸收量翻倍，并把吸收的伤害转为法术强度，攻防一体。\n\n### 来源\nwowstar.online社区推荐专精。', 'spell_shadow_unholystrength', 0, 1795651200, 1795651200, 1, 15, 3, 0, 0),
(1009, '44e9be1a-635e-5694-923b-9592ea341760', '', '', '', 25, 'Sidekick', '邪教徒 · 神刃', '以恩佐斯之力强化武器与近战攻势。', '### 概述\n神刃（Godblade）· 邪教徒 专精\n\n### 定位\nDPS（近战与施法混合）\n\n官方简介：以恩佐斯之力强化武器与近战攻势。\n\n### 核心\n神刃（God Blade，r5,c7）：使 Rift 必定暴击 Hammer of Twilight，是该流派整套循环的核心爆发连招。\n\n### 来源\nwowstar.online社区推荐专精。', 'spell_shadow_unholystrength', 0, 1795651200, 1795651200, 1, 15, 3, 0, 0),
(1010, 'eef74476-0c19-5819-ba7a-8a047ec27c3a', '', '', '', 25, 'Sidekick', '邪教徒 · 异端', '借助尤格萨隆之力，在近战中治疗和保护盟友。', '### 概述\n异端（Heretic）· 邪教徒 专精\n\n### 定位\n治疗\n\n官方简介：借助尤格萨隆之力，在近战中治疗和保护盟友。\n\n### 核心\n深渊契约（Abyssal Covenant，r2,c4）：坦克治疗式伤害链接机制；其余天赋（Dark Protection、Lead the Covenant、Visions of the Empire、Dark Prophet）都在放大这条链路。\n\n### 来源\nwowstar.online社区推荐专精。', 'spell_shadow_unholystrength', 0, 1795651200, 1795651200, 1, 15, 3, 0, 0),
(1011, 'a2c97d19-4b3d-5a12-bf20-294ce6372869', '', '', '', 14, 'Sidekick', '恶魔猎手 · 地狱火', '驾驭邪能法术与恶魔之力，以猛烈的远程攻势摧毁敌人。', '### 概述\n地狱火（Infernal）· 恶魔猎手 专精\n\n### 定位\n远程施法 DPS（智力／精神，DoT 与爆发）\n\n官方简介：驾驭邪能法术与恶魔之力，以猛烈的远程攻势摧毁敌人。\n\n### 核心\n毁灭（Ruin，r0,c4）：倾泻邪能的核弹；其余 Infernal 天赋（Bane of Chaos 的生成、Black Magic、Fel Cannon、Curse of Argus）都为它供能与放大。\n\n### 来源\nwowstar.online社区推荐专精。', 'ability_demonhunter_metamorphasis', 0, 1795651200, 1795651200, 1, 15, 2, 0, 0),
(1012, 'b688c538-1d11-52e0-92c9-b99478a1fe65', '', '', '', 14, 'Sidekick', '恶魔猎手 · 屠戮', '以邪能强化武器，凭借迅捷的双持攻击追击敌人。', '### 概述\n屠戮（Slayer）· 恶魔猎手 专精\n\n### 定位\n近战 DPS（双持／敏捷／邪能循环）\n\n官方简介：以邪能强化武器，凭借迅捷的双持攻击追击敌人。\n\n### 核心\n埃辛诺斯突袭（Azzinoth''s Assault，r0,c4）：核心邪能消耗技，整套循环围绕 Annihilan Strike/Twin Slice 接 Assault 展开。\n\n### 来源\nwowstar.online社区推荐专精。', 'ability_demonhunter_metamorphasis', 0, 1795651200, 1795651200, 1, 15, 2, 0, 0),
(1013, '2f44534f-878a-5334-8678-0f3972f71144', '', '', '', 14, 'Sidekick', '恶魔猎手 · 暴君', '强化恶魔形态，挥舞双刃抵御攻击，牢牢控制战场。', '### 概述\n暴君（Tyrant）· 恶魔猎手 专精\n\n### 定位\n坦克（闪避／招架，双持双手武器）\n\n官方简介：强化恶魔形态，挥舞双刃抵御攻击，牢牢控制战场。\n\n### 核心\n劈砍（Carve，r0,c4）：引导式邪能消耗技，是全套技能的地基；终极方向是 Tyrannical Resolve 的「打不死＋群体嘲讽」。\n\n### 来源\nwowstar.online社区推荐专精。', 'ability_demonhunter_metamorphasis', 0, 1795651200, 1795651200, 1, 15, 2, 0, 0),
(1014, '687cc102-ef2f-5a35-8ce0-ec8cd0dc7aef', '', '', '', 17, 'Sidekick', '克索诺斯骑士 · 抗争', '统御克索诺斯恶魔，抵御敌人的攻击。', '### 概述\n抗争（Defiance）· 克索诺斯骑士 专精\n\n### 定位\n坦克\n\n官方简介：统御克索诺斯恶魔，抵御敌人的攻击。\n\n### 核心\n召唤小鬼（Impcaller，r2,c4）：让 Infernal Strike 本身顺带召唤小鬼，使小鬼常驻从「按技能」变成「按循环自动产生」。\n\n### 来源\nwowstar.online社区推荐专精。', 'spell_fire_hellfire', 0, 1795651200, 1795651200, 1, 15, 1, 0, 0),
(1015, 'e7bd3a40-a818-5b02-9612-464e4530a4fd', '', '', '', 17, 'Sidekick', '克索诺斯骑士 · 地狱烈焰', '结合近战攻击与地狱烈焰法术。', '### 概述\n地狱烈焰（Hellfire）· 克索诺斯骑士 专精\n\n### 定位\n远程 DPS\n\n官方简介：结合近战攻击与地狱烈焰法术。\n\n### 核心\n燃烧之力（Burning Power，r2,c10）：20 级被动，把 100% 智力转为攻击强度、50% 力量转为法术伤害；整套伤害计算都建在它之上。\n\n### 来源\nwowstar.online社区推荐专精。', 'spell_fire_hellfire', 0, 1795651200, 1795651200, 1, 15, 1, 0, 0),
(1016, '789fa92b-5ad9-5f8f-a0a6-227240307372', '', '', '', 17, 'Sidekick', '克索诺斯骑士 · 战争', '以双手武器重击积蓄恶魔之火。', '### 概述\n战争（War）· 克索诺斯骑士 专精\n\n### 定位\n近战 DPS\n\n官方简介：以双手武器重击积蓄恶魔之火。\n\n### 核心\n凶残之力（Murderous Might，r5,c2）：所有消耗魔火的技能伤害 +25%，是整套构筑里最大的伤害乘区。\n\n### 来源\nwowstar.online社区推荐专精。', 'spell_fire_hellfire', 0, 1795651200, 1795651200, 1, 15, 1, 0, 0),
(1017, 'e6b5b830-e437-55b8-aacf-8a36cf0c8dd1', '', '', '', 18, 'Sidekick', '守护者 · 角斗士', '以盾与剑进攻，控制并压制对手。', '### 概述\n角斗士（Gladiator）· 守护者 专精\n\n### 定位\nDPS（近战）\n\n官方简介：以盾与剑进攻，控制并压制对手。\n\n### 核心\n荣耀（Glory，r0,c10）：叠层被动，每 30 秒必定打出一次 150% 伤害的冲撞，再接 Favor 叠到 500% 武器伤害的平砍。\n\n### 来源\nwowstar.online社区推荐专精。', 'inv_shield_06', 0, 1795651200, 1795651200, 1, 15, 1, 0, 0),
(1018, '7ec66a58-45aa-5b99-8931-8b2d771c42ac', '', '', '', 18, 'Sidekick', '守护者 · 激励', '以战旗、战歌与号召鼓舞盟友。', '### 概述\n激励（Inspiration）· 守护者 专精\n\n### 定位\n辅助\n\n官方简介：以战旗、战歌与号召鼓舞盟友。\n\n### 核心\n鼓舞领袖（Inspiring Leader，r0,c4）：单点点出后把 Pulverize 与 Broad Sweep 变成「战歌」，把共用的近战底盘转成增益／辅助定位。\n\n### 来源\nwowstar.online社区推荐专精。', 'inv_shield_06', 0, 1795651200, 1795651200, 1, 15, 1, 0, 0),
(1019, '0f859ce8-00ac-5d99-8fcd-097375e1e447', '', '', '', 18, 'Sidekick', '守护者 · 先锋', '运用盾牌格挡，抵挡猛烈攻击。', '### 概述\n先锋（Vanguard）· 守护者 专精\n\n### 定位\n坦克\n\n官方简介：运用盾牌格挡，抵挡猛烈攻击。\n\n### 核心\n壁垒（Bastion，r9,c4）：群体承受伤害 -40% 的团队减伤，由 Raise Shield／Brace 的覆盖率链驱动。\n\n### 来源\nwowstar.online社区推荐专精。', 'inv_shield_06', 0, 1795651200, 1795651200, 1, 15, 1, 0, 0),
(1020, '886746c6-20a9-5d34-99d6-ff9913a9dee9', '', '', '', 19, 'Sidekick', '圣殿骑士 · 十字军', '释放誓言之力，横扫面前的敌人。', '### 概述\n十字军（Crusader）· 圣殿骑士 专精\n\n### 定位\n近战 DPS（吸血自疗混合）\n\n官方简介：释放誓言之力，横扫面前的敌人。\n\n### 核心\n银刃（Argent Blade，r1,c4）：自带治疗的核心构建／终结技，定义其吸血 DPS 定位，也让单人续航不靠药。\n\n### 来源\nwowstar.online社区推荐专精。', 'spell_holy_sealofmight', 0, 1795651200, 1795651200, 1, 15, 1, 0, 0),
(1021, '89afa479-ef6b-5db7-8237-753c60abab9f', '', '', '', 19, 'Sidekick', '圣殿骑士 · 守誓者', '招架并延缓伤害，伺机反击。', '### 概述\n守誓者（Oathkeeper）· 圣殿骑士 专精\n\n### 定位\n坦克\n\n官方简介：招架并延缓伤害，伺机反击。\n\n### 核心\n恪守誓约（Keeping the Oath，r0,c10）：10 级被动，把 40% 直接伤害摊成可控 DoT，并让 Oath Breakers 不再消耗誓约。\n\n### 来源\nwowstar.online社区推荐专精。', 'spell_holy_sealofmight', 0, 1795651200, 1795651200, 1, 15, 1, 0, 0),
(1022, '214d0135-ff9f-5c6a-99fc-24bf86aa446f', '', '', '', 19, 'Sidekick', '圣殿骑士 · 狂热者', '以连续攻势突破敌人的防御。', '### 概述\n狂热者（Zealot）· 圣殿骑士 专精\n\n### 定位\n近战 DPS（物理与神圣混合）\n\n官方简介：以连续攻势突破敌人的防御。\n\n### 核心\n昭雪（Vindication，r0,c4）：触发 Zealotry 并授予誓约的入门构建技，是整套触发与终结循环的点火点。\n\n### 来源\nwowstar.online社区推荐专精。', 'spell_holy_sealofmight', 0, 1795651200, 1795651200, 1, 15, 1, 0, 0),
(1023, 'dd51d1c6-8b35-5410-b3dc-af3bf42fc64a', '', '', '', 23, 'Sidekick', '死灵法师 · 亡灵复生', '唤起亡灵大军，强化仆从并指挥它们压倒敌人。', '### 概述\n亡灵复生（Animation）· 死灵法师 专精\n\n### 定位\n宠物／召唤 DPS（可借小怪客串坦克）\n\n官方简介：唤起亡灵大军，强化仆从并指挥它们压倒敌人。\n\n### 核心\n血肉共生（Flesh Symbiosis，r8,c2）：每个在场的憎恶／腐朽巨像提供 +30% 护甲与法术抗性，并每 5 秒回复 2% 最大生命。\n\n### 来源\nwowstar.online社区推荐专精。', 'spell_shadow_raisedead', 0, 1795651200, 1795651200, 1, 15, 3, 0, 0),
(1024, '38e2df22-50c9-573f-b2c1-888e9970f7ae', '', '', '', 23, 'Sidekick', '死灵法师 · 死亡', '以疫病和死亡魔法侵蚀敌人，统御亡灵为你作战。', '### 概述\n死亡（Death）· 死灵法师 专精\n\n### 定位\n远程 DPS（瘟疫／疾病，符文能量）\n\n官方简介：以疫病和死亡魔法侵蚀敌人，统御亡灵为你作战。\n\n### 核心\n清除（Expunge，r4,c2）：后续所有疾病系天赋都在放大它施加的「疾病易伤」debuff，是整套伤害引擎。\n\n### 来源\nwowstar.online社区推荐专精。', 'spell_shadow_raisedead', 0, 1795651200, 1795651200, 1, 15, 3, 0, 0),
(1025, '4b6359f3-72f9-5eb8-a971-c31017e014ee', '', '', '', 23, 'Sidekick', '死灵法师 · 霜寒', '运用诺森德的冰霜魔法控制敌人，与亡灵仆从协同作战。', '### 概述\n霜寒（Rime）· 死灵法师 专精\n\n### 定位\n远程 DPS（冰霜爆发／暴击）\n\n官方简介：运用诺森德的冰霜魔法控制敌人，与亡灵仆从协同作战。\n\n### 核心\n冰川冲击（Glacial Impact，r2,c6）：需冻结目标；Glacier Lord、Frigidness、Frigid Death、Harrowing Winds、Master Lich 全都只为放大它。\n\n### 来源\nwowstar.online社区推荐专精。', 'spell_shadow_raisedead', 0, 1795651200, 1795651200, 1, 15, 3, 0, 0),
(1026, 'e1e1e900-a154-59f7-a786-f246441f503a', '', '', '', 29, 'Sidekick', '剧毒术士 · 坚韧', '以甲虫形态承接攻击，管理怒气与暴露血肉，用甲壳保护自己并反击。', '### 概述\n坚韧（Fortitude）· 剧毒术士 专精\n\n### 定位\n坦克\n\n官方简介：以甲虫形态承接攻击，管理怒气与暴露血肉，用甲壳保护自己并反击。\n\n### 核心\n暴露血肉（Exposed Flesh，r0,c10）[A]：受击叠层产生怒气，供全树的减伤与仇恨技消耗。\n\n### 来源\nwowstar.online社区推荐专精。', 'ability_creature_poison_05', 0, 1795651200, 1795651200, 1, 15, 3, 0, 0),
(1027, 'ad64766f-7dc3-57e1-b140-b341e554ca21', '', '', '', 29, 'Sidekick', '剧毒术士 · 腐毒', '交织枯萎、孢子与真菌增生，用毒液箭和霉菌病侵蚀敌人。', '### 概述\n腐毒（Rot）· 剧毒术士 专精\n\n### 定位\n治疗（伤害驱动／周期性治疗）\n\n官方简介：交织枯萎、孢子与真菌增生，用毒液箭和霉菌病侵蚀敌人。\n\n### 核心\n腐化巫妖（Rot Lich，r0,c10）[A]：伤害暴击触发一次免费瞬发的毒牙，是「DoT 施法者当治疗」的核心循环。\n\n### 来源\nwowstar.online社区推荐专精。', 'ability_creature_poison_05', 0, 1795651200, 1795651200, 1, 15, 3, 0, 0),
(1028, 'b82f7ae3-c4a6-5b02-b100-02182983aa84', '', '', '', 29, 'Sidekick', '剧毒术士 · 潜猎', '潜伏于蜘蛛形态，积累孵化印记，以毒牙和消耗印记的技能击溃敌人。', '### 概述\n潜猎（Stalking）· 剧毒术士 专精\n\n### 定位\n近战 DPS\n\n官方简介：潜伏于蜘蛛形态，积累孵化印记，以毒牙和消耗印记的技能击溃敌人。\n\n### 核心\n巢群印记（Brood Marks，r0,c10）[A]：毒牙积攒连击点式资源，所有消耗技（Facemelter、Blistering Fangs、Venomous Bite）都围绕消耗它。\n\n### 来源\nwowstar.online社区推荐专精。', 'ability_creature_poison_05', 0, 1795651200, 1795651200, 1, 15, 3, 0, 0),
(1029, '49e6f876-b676-5aba-a0c5-8c426eb0db3d', '', '', '', 29, 'Sidekick', '剧毒术士 · 维齐尔', '借沙德拉的力量施加药膏与祝福，用毒蛇之牙和万能溶剂治疗盟友。', '### 概述\n维齐尔（Vizier）· 剧毒术士 专精\n\n### 定位\n治疗（直接治疗／团队）\n\n官方简介：借沙德拉的力量施加药膏与祝福，用毒蛇之牙和万能溶剂治疗盟友。\n\n### 核心\n沙德拉守望（Shadra''s Vigil，r0,c10）[A]：毒牙为目标叠出 5 层周期性治疗增幅，整套技能都在维持刷新它。\n\n### 来源\nwowstar.online社区推荐专精。', 'ability_creature_poison_05', 0, 1795651200, 1795651200, 1, 15, 3, 0, 0),
(1030, '141a2dfe-2e5e-5970-a6d8-2c5b66d1e11c', '', '', '', 24, 'Sidekick', '炎术师 · 龙焰', '以近距离火焰法术积蓄吐息充能，再释放毁灭性的龙息。', '### 概述\n龙焰（Draconic）· 炎术师 专精\n\n### 定位\n远程 DPS\n\n官方简介：以近距离火焰法术积蓄吐息充能，再释放毁灭性的龙息。\n\n### 核心\n龙族祈唤（Draconic Invocation，r5,c4）：立即生成 5 点余烬的开场爆发冷却，为 Black Magic、Invocation of Flame 等供能。\n\n### 来源\nwowstar.online社区推荐专精。', 'spell_fire_fireball', 0, 1795651200, 1795651200, 1, 15, 3, 0, 0),
(1031, 'd8912336-d3ec-5fe2-8fba-55f9044841f3', '', '', '', 24, 'Sidekick', '炎术师 · 织焰', '编织治愈之焰、灼合伤口，以火焰魔法守护盟友。', '### 概述\n织焰（Flameweaving）· 炎术师 专精\n\n### 定位\n治疗\n\n官方简介：编织治愈之焰、灼合伤口，以火焰魔法守护盟友。\n\n### 核心\n凤凰之卵（Phoenix Egg，r0,c4）：召唤治疗宠的引擎，其余天赋（Kael''s Command、Offering of Executus、Invigoration、Fueling the Fire）围绕它构建。\n\n### 来源\nwowstar.online社区推荐专精。', 'spell_fire_fireball', 0, 1795651200, 1795651200, 1, 15, 3, 0, 0),
(1032, '277593fb-ebf4-5255-aee6-9aeeb65f3d3d', '', '', '', 24, 'Sidekick', '炎术师 · 焚烧', '以炽烈法术与持续燃烧交织进攻，让敌人在烈焰中化为灰烬。', '### 概述\n焚烧（Incineration）· 炎术师 专精\n\n### 定位\n远程 DPS\n\n官方简介：以炽烈法术与持续燃烧交织进攻，让敌人在烈焰中化为灰烬。\n\n### 核心\n烈焰崩裂（Pyroclasm，r8,c6）：吃掉目标身上全部点燃类周期效果，打出「双倍总量＋固定值」的爆发核弹。\n\n### 来源\nwowstar.online社区推荐专精。', 'spell_fire_fireball', 0, 1795651200, 1795651200, 1, 15, 3, 0, 0),
(1033, '76f95581-ea0b-5991-89cb-22e7f6903dfd', '', '', '', 21, 'Sidekick', '游侠 · 箭术', '运用箭袋与远程武器精准射击。', '### 概述\n箭术（Archery）· 游侠 专精\n\n### 定位\n远程 DPS\n\n官方简介：运用箭袋与远程武器精准射击。\n\n### 核心\n精准射击（Precision Shot，r0,c4）：整棵专精树都在给这一发核弹叠倍率（Swiftshot、New-Age Archery、Masterful Archery 等）。\n\n### 来源\nwowstar.online社区推荐专精。', 'inv_weapon_bow_07', 0, 1795651200, 1795651200, 1, 15, 2, 0, 0),
