(1037, '5b45df48-b038-5608-995d-763ccf8b70da', '', '', '', 30, 'Sidekick', '死神 · 收割', '收割敌人生命精华，强化重型双手武器打击，依靠窃取的生命力维持持续攻势。', '### 概述\n收割（Harvest）· 死神 专精\n\n### 定位\n坦克／自续航斗士\n\n官方简介：收割敌人生命精华，强化重型双手武器打击，依靠窃取的生命力维持持续攻势。\n\n### 核心\n收割者（Harvester，r0,c10）[A]：造成伤害的 15% 转化为自愈，整套坦克定位围绕它运转。\n\n### 来源\nwowstar.online社区推荐专精。', 'spell_deathknight_bloodpresence', 0, 1795651200, 1795651200, 1, 15, 2, 0, 0),
