(1039, 'daeb2866-e47e-5a7f-984d-54c8ca5e8433', '', '', '', 20, 'Sidekick', '血法师 · 诅咒', '以受诅咒的形态结合近战攻击与法术。', '### 概述\n诅咒（Accursed）· 血法师 专精\n\n### 定位\n近战 / 施法者（诅咒形态）\n\n官方简介：以受诅咒的形态结合近战攻击与法术。\n\n### 核心\n诅咒形态（Accursed Form，r0,c4）：把敏捷转为攻击力的变身，是该专精全部的近战身份。\n\n### 来源\nwowstar.online社区推荐专精。', 'spell_shadow_bloodboil', 0, 1795651200, 1795651200, 1, 15, 3, 0, 0),
