(1044, '44c8e130-207e-55f2-ba72-31b0c753b4d2', '', '', '', 32, 'Sidekick', '符文大师 · 符印', '交织冰霜、火焰与奥术符印。', '### 概述\n符印（Glyphic）· 符文大师 专精\n\n### 定位\n远程 DPS\n\n官方简介：交织冰霜、火焰与奥术符印。\n\n### 核心\n奥术符文（Arcane Glyph，r2,c4）：补全「冰霜→火焰→奥术」的符文链，解锁最强 Unleash 层级。\n\n### 来源\nwowstar.online社区推荐专精。', 'inv_misc_rune_06', 0, 1795651200, 1795651200, 1, 15, 3, 0, 0),
(1045, 'a53829fa-3863-5256-867d-c41de0effa4e', '', '', '', 32, 'Sidekick', '符文大师 · 裂隙之刃', '以双手武器释放猛烈的魔法攻击。', '### 概述\n裂隙之刃（Riftblade）· 符文大师 专精\n\n### 定位\n近战 DPS\n\n官方简介：以双手武器释放猛烈的魔法攻击。\n\n### 核心\n元素刺客（Elemental Assassin，r2,c10）：把敏捷转为法术伤害／暴击／命中，使近战装备同时强化法系技能。\n\n### 来源\nwowstar.online社区推荐专精。', 'inv_misc_rune_06', 0, 1795651200, 1795651200, 1, 15, 3, 0, 0),
(1046, '0c68a284-e4ca-5332-8b04-edf91cfce475', '', '', '', 26, 'Sidekick', '唤星者 · 月守卫', '以法力强化防御，守护宇宙的秘密。', '### 概述\n月守卫（Moon Guard）· 唤星者 专精\n\n### 定位\n坦克（格挡与散星减伤）\n\n官方简介：以法力强化防御，守护宇宙的秘密。\n\n### 核心\n星毯（Blanket of Stars，r1,c3）：格挡率／格挡值冷却，其余节点（Nebula、Dance In The Starlight 等）都在延长或强化它。\n\n### 来源\nwowstar.online社区推荐专精。', 'ability_druid_starfall', 0, 1795651200, 1795651200, 1, 15, 3, 0, 0),
(1047, 'b05ad96c-45aa-59aa-9529-379ad1e9585e', '', '', '', 26, 'Sidekick', '唤星者 · 月之祭司', '运用月相与魔法之水治愈盟友。', '### 概述\n月之祭司（Moon Priest）· 唤星者 专精\n\n### 定位\n治疗（团队治疗，法力与月相引擎）\n\n官方简介：运用月相与魔法之水治愈盟友。\n\n### 核心\n女神化身（Aspect of the Goddess，r0,c4）：常驻治疗形态，提升治疗、保证不 miss，并把散星消耗转为群体治疗。\n\n### 来源\nwowstar.online社区推荐专精。', 'ability_druid_starfall', 0, 1795651200, 1795651200, 1, 15, 3, 0, 0),
(1048, 'feb803d4-91a9-5164-950b-39452de21394', '', '', '', 26, 'Sidekick', '唤星者 · 哨兵', '以月光强化箭矢，远程打击敌人。', '### 概述\n哨兵（Sentinel）· 唤星者 专精\n\n### 定位\n远程物理／奥术 DPS（猎人式风筝）\n\n官方简介：以月光强化箭矢，远程打击敌人。\n\n### 核心\n星火射击（Starfire Shot，r0,c4）：消耗散星的标志性核弹，Tyrande''s Training、Sentinel''s Focus、Starfire Power 都为它缩放。\n\n### 来源\nwowstar.online社区推荐专精。', 'ability_druid_starfall', 0, 1795651200, 1795651200, 1, 15, 3, 0, 0),
(1049, '94cfc483-6df7-52d7-b1c2-6020832fc7c0', '', '', '', 26, 'Sidekick', '唤星者 · 守望者', '以月刃和月光攻击惩戒敌人。', '### 概述\n守望者（Warden）· 唤星者 专精\n\n### 定位\n近战 DPS（法力驱动的游击与爆发）\n\n官方简介：以月刃和月光攻击惩戒敌人。\n\n### 核心\n星刃（Astral Blade，r1,c4）：抽取法力的精准打击，其余核心节点（Fury of the Stars、Maiev''s Guard 等）都为它供能。\n\n### 来源\nwowstar.online社区推荐专精。', 'ability_druid_starfall', 0, 1795651200, 1795651200, 1, 15, 3, 0, 0),
(1050, 'bd3fdc9c-e414-5c54-84cd-02a66aad7fd0', '', '', '', 16, 'Sidekick', '风暴使者 · 闪电', '释放电能爆发与连锁闪电。', '### 概述\n闪电（Lightning）· 风暴使者 专精\n\n### 定位\n远程 DPS\n\n官方简介：释放电能爆发与连锁闪电。\n\n### 核心\n托里姆之臂（Arm of Thorim）：倾泻静电的核弹；Superconductor 按消耗的静电缩放它，Electric Energy 与 Invoking Storms 直接增伤。\n\n### 来源\nwowstar.online社区推荐专精。', 'spell_nature_lightning', 0, 1795651200, 1795651200, 1, 15, 3, 0, 0),
(1051, '58152132-48b4-5d50-aa02-99ba2124eee8', '', '', '', 16, 'Sidekick', '风暴使者 · 漩涡', '交织水与闪电，释放风暴法术。', '### 概述\n漩涡（Maelstrom）· 风暴使者 专精\n\n### 定位\n远程 DPS（自续航／消耗战）\n\n官方简介：交织水与闪电，释放风暴法术。\n\n### 核心\n风涌（Stormflow）：引导光束，同时是主伤害来源、唯一稳定的自愈（借 Blessing of Lei Shen），也是 Conduit 电刑放大与免费施法的开启器。\n\n### 来源\nwowstar.online社区推荐专精。', 'spell_nature_lightning', 0, 1795651200, 1795651200, 1, 15, 3, 0, 0),
(1052, '3b321718-2ecc-596e-8dd6-2213356ba659', '', '', '', 16, 'Sidekick', '风暴使者 · 疾风', '操控疾风与风之仆从，支援盟友并控制敌人。', '### 概述\n疾风（Wind）· 风暴使者 专精\n\n### 定位\n控制／辅助\n\n官方简介：操控疾风与风之仆从，支援盟友并控制敌人。\n\n### 核心\n风元素（Air Elemental）：整棵树围绕让这只宠物活着、被强化、并周期性被 Unshackle 赋能；其余节点或供能于它、或由它供能。\n\n### 来源\nwowstar.online社区推荐专精。', 'spell_nature_lightning', 0, 1795651200, 1795651200, 1, 15, 3, 0, 0),
(1053, '1737f4ac-6a63-528c-acb4-35511e7afaca', '', '', '', 27, 'Sidekick', '太阳祭司 · 祝福', '赐福盟友并施加守护祝福，以辉耀连锁、破晓和神圣形态维持团队生命。', '### 概述\n祝福（Blessings）· 太阳祭司 专精\n\n### 定位\n治疗\n\n官方简介：赐福盟友并施加守护祝福，以辉耀连锁、破晓和神圣形态维持团队生命。\n\n### 核心\n太阳崇拜（Sun Worship，r2,c10）：20 级被动，把智力同时转为治疗强度与法术急速，是其余一切的永久乘区。\n\n### 来源\nwowstar.online社区推荐专精。', 'spell_holy_heal', 0, 1795651200, 1795651200, 1, 15, 4, 0, 0),
(1054, '23e01aa0-f60e-5d31-885d-6995d2ff7e74', '', '', '', 27, 'Sidekick', '太阳祭司 · 虔诚', '交替运用日出与日落，以神圣和火焰法术贯穿敌人，用太阳烈焰延续攻势。', '### 概述\n虔诚（Piety）· 太阳祭司 专精\n\n### 定位\n远程 DPS（火焰／神圣）\n\n官方简介：交替运用日出与日落，以神圣和火焰法术贯穿敌人，用太阳烈焰延续攻势。\n\n### 核心\n日冕协奏（Solar Concord，r4,c4）：在「日出」重置 Horusath Blast、在「日落」重置 Rapture，并在其基础上打出太阳耀斑。\n\n### 来源\nwowstar.online社区推荐专精。', 'spell_holy_heal', 0, 1795651200, 1795651200, 1, 15, 4, 0, 0),
(1055, '94f51e4a-2e87-5082-91c1-0f03c8713023', '', '', '', 27, 'Sidekick', '太阳祭司 · 炽天使', '以盾牌承接攻击，将格挡与圣光治疗化为屏障，召唤列王之锤守卫盟友。', '### 概述\n炽天使（Seraphim）· 太阳祭司 专精\n\n### 定位\n坦克\n\n官方简介：以盾牌承接攻击，将格挡与圣光治疗化为屏障，召唤列王之锤守卫盟友。\n\n### 核心\n炽天使壁垒（Seraphic Bulwark，r2,c6）：2 层充能、令接下来数次格挡的格挡值翻倍，是整套坦克装备循环的核心减伤。\n\n### 来源\nwowstar.online社区推荐专精。', 'spell_holy_heal', 0, 1795651200, 1795651200, 1, 15, 4, 0, 0),
(1056, 'ca79bb13-1674-5f01-ba30-c20fc097027d', '', '', '', 27, 'Sidekick', '太阳祭司 · 女武神', '双持重型武器，履行女武神誓言，以荣耀处决、正义旋击和空中突击压制敌人。', '### 概述\n女武神（Valkyrie）· 太阳祭司 专精\n\n### 定位\n近战 DPS（双持）\n\n官方简介：双持重型武器，履行女武神誓言，以荣耀处决、正义旋击和空中突击压制敌人。\n\n### 核心\n女武神誓约（Vow of the Valkyr，r6,c10）：普攻产生太阳之力，其「履行」触发额外挥砍，是整套循环的资源环。\n\n### 来源\nwowstar.online社区推荐专精。', 'spell_holy_heal', 0, 1795651200, 1795651200, 1, 15, 4, 0, 0),
(1057, 'b82240e6-e632-5c48-8039-6dc85ddebd4f', '', '', '', 28, 'Sidekick', '工匠 · 爆破', '使用炸药、火箭与机关摧毁敌人。', '### 概述\n爆破（Demolition）· 工匠 专精\n\n### 定位\n远程 DPS（火焰／远程攻强轰炸）\n\n官方简介：使用炸药、火箭与机关摧毁敌人。\n\n### 核心\n曳光增幅（Tracer Augmentation，r6,c2）：叠标记再引爆的引擎，由 Rocket Engineering 加速，火箭弹幕与火箭炮台结算收益。\n\n### 来源\nwowstar.online社区推荐专精。', 'inv_gizmo_02', 0, 1795651200, 1795651200, 1, 15, 2, 0, 0),
(1058, 'daf1946d-470c-5341-95be-b6b6fab3ff11', '', '', '', 28, 'Sidekick', '工匠 · 发明', '用纳米机器人、药剂与信标治疗盟友。', '### 概述\n发明（Invention）· 工匠 专精\n\n### 定位\n治疗\n\n官方简介：用纳米机器人、药剂与信标治疗盟友。\n\n### 核心\n我最伟大的发明！（My Greatest Invention!，r8,c2）：标志性团队治疗冷却，Epiphany! 借 Beacon 施法进一步缩短其冷却。\n\n### 来源\nwowstar.online社区推荐专精。', 'inv_gizmo_02', 0, 1795651200, 1795651200, 1, 15, 2, 0, 0),
(1059, 'd39d3ac3-09c7-5ab4-8448-e1a3b269ab63', '', '', '', 28, 'Sidekick', '工匠 · 机械学', '升级炮台与机械伙伴，收集零件操纵机甲。', '### 概述\n机械学（Mechanics）· 工匠 专精\n\n### 定位\n近战／远程混合 DPS（机甲技能＋宠物，废料资源）\n\n官方简介：升级炮台与机械伙伴，收集零件操纵机甲。\n\n### 核心\n过载（Overload，r5,c2）：40% 概率让机甲：燃烧／激光束双次打击，是该专精的爆发上限，由 Mechanical Extender 的叠层触发率直接供能。\n\n### 来源\nwowstar.online社区推荐专精。', 'inv_gizmo_02', 0, 1795651200, 1795651200, 1, 15, 2, 0, 0),
