(1066, '4771fc4a-5e03-58eb-8944-5459a146c6fd', '', '', '', 13, 'Sidekick', '巫医 · 巫毒', '运用巫毒法术削弱敌人，操纵战局。', '### 概述\n巫毒（Voodoo）· 巫医 专精\n\n### 定位\n远程 DPS（精神缩放的暗影／火焰）\n\n官方简介：运用巫毒法术削弱敌人，操纵战局。\n\n### 核心\n坏巫毒（Bad Juju，r2,c2）：按精神缩放的核弹，其余 Voodoo 节点（Ritual Hexing、Overflowing Juju ×2、Malignant 等）都围绕它。\n\n### 来源\nwowstar.online社区推荐专精。', 'spell_shadow_hex', 0, 1795651200, 1795651200, 1, 15, 3, 0, 0),
(1067, 'c48a9081-bced-58a7-9816-d9b43247ffb2', '', '', '', 15, 'Sidekick', '猎魔人 · 黑骑士', '挥舞双手剑偏转攻击，守护盟友。', '### 概述\n黑骑士（Black Knight）· 猎魔人 专精\n\n### 定位\n坦克／自愈近战（双手武器）\n\n官方简介：挥舞双手剑偏转攻击，守护盟友。\n\n### 核心\n夜刃（Noctis Blade，r0,c4）：按需使用的吸血打击，其余天赋（Wide Swings、Noctis Protection、Undying 等）靠强化或触发它。\n\n### 来源\nwowstar.online社区推荐专精。', 'inv_weapon_crossbow_02', 0, 1795651200, 1795651200, 1, 15, 2, 0, 0),
(1068, 'f532abb3-e242-53f9-a1b7-0c8933fe8430', '', '', '', 15, 'Sidekick', '猎魔人 · 疾弩手', '以灵活机动的弩箭攻击远处敌人。', '### 概述\n疾弩手（Boltslinger）· 猎魔人 专精\n\n### 定位\n远程物理／暮光 DPS（怒气，弩）\n\n官方简介：以灵活机动的弩箭攻击远处敌人。\n\n### 核心\n追心弩矢（Heartseeking Bolt，r2,c4）：按斩杀缩放的核弹，Kingdom Hearts（20% 以下必暴）、One Shot、Bane of Witches 都围绕它。\n\n### 来源\nwowstar.online社区推荐专精。', 'inv_weapon_crossbow_02', 0, 1795651200, 1795651200, 1, 15, 2, 0, 0),
(1069, '80547259-ce63-55d8-bda4-24497f1c5b47', '', '', '', 15, 'Sidekick', '猎魔人 · 驯犬者', '与暗影猎犬协同，使用枪械追猎敌人。', '### 概述\n驯犬者（Houndmaster）· 猎魔人 专精\n\n### 定位\n远程 DPS＋永久宠物（暗影猎犬）\n\n官方简介：与暗影猎犬协同，使用枪械追猎敌人。\n\n### 核心\n放犬（Unleash the Hounds，r0,c4）：召唤爆发的核心，下游（Kennel Master、Decimate、Houndfeeder）全部为放大它而点。\n\n### 来源\nwowstar.online社区推荐专精。', 'inv_weapon_crossbow_02', 0, 1795651200, 1795651200, 1, 15, 2, 0, 0),
(1070, 'c54805ab-dac5-5cf9-8715-5ac2c4568293', '', '', '', 15, 'Sidekick', '猎魔人 · 异端审判', '双持武器，以审判烈焰惩戒敌人。', '### 概述\n异端审判（Inquisition）· 猎魔人 专精\n\n### 定位\n近战 DPS\n\n官方简介：双持武器，以审判烈焰惩戒敌人。\n\n### 核心\n炽焰裁决（Fiery Judgement，r4,c2）：范围火焰／神圣核弹，同时刷新「罪火」，把两条属性线（敏捷转火法伤、智力转攻强）串起来。\n\n### 来源\nwowstar.online社区推荐专精。', 'inv_weapon_crossbow_02', 0, 1795651200, 1795651200, 1, 15, 2, 0, 0);

